function kEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function kSlot(i){return i===undefined?document.querySelector('[data-stage]'):document.querySelector('[data-state="'+i+'"]');}
var LR={plain:['Share the transcript',[['Zach',''],['Open','']],'Offered at the start so he would not need notes.','S1 [5:05]'],grain:['Times by Fri 11-13',[['Grade D',''],['n = 0','']],'60%, a judgment with no base rate yet.','No base rate'],moire:['Times for next week',[['Brian',''],['Summary wrong','']],'He asked to schedule; the summary assigned it to Zach.','S1 [83:01]']};
function kitLedgerRow(r,state){return '<div class="ledger-row'+(state&&state!=='plain'?' '+state:'')+'"><div class="lr-key">'+kEsc(r[0])+'</div><div class="lr-body"><div class="lr-chips">'+r[1].map(function(c){return '<span class="chip'+(c[1]?' '+c[1]:'')+'">'+kEsc(c[0])+'</span>'}).join('')+'</div><span>'+kEsc(r[2])+'</span><span class="ref">'+kEsc(r[3])+'</span></div></div>'}
function kitLedger(host,rows){var w=document.createElement('div');w.className='ledger';w.innerHTML=rows.map(function(x){return kitLedgerRow(LR[x],x)}).join('');host.appendChild(w);return w}
kitLedger(kSlot(),['plain','grain','moire']);
STATES.forEach(function(a,i){var b=document.createElement('div');b.style.maxWidth=a[1];kSlot(i).appendChild(b);kitLedger(b,[a[0]])});
